 void InitTheme(){
  Resources[SystemColors.WindowBrushKey]=panel;Resources[SystemColors.ControlBrushKey]=panel;Resources[SystemColors.ControlTextBrushKey]=Brushes.White;Resources[SystemColors.WindowTextBrushKey]=Brushes.White;
  string combo=@"<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='ComboBox'><Setter Property='Foreground' Value='#d5dce0'/><Setter Property='Background' Value='#354048'/><Setter Property='Padding' Value='7,4'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ComboBox'><Grid><ToggleButton Focusable='False' IsChecked='{Binding IsDropDownOpen,Mode=TwoWay,RelativeSource={RelativeSource TemplatedParent}}'><ToggleButton.Template><ControlTemplate TargetType='ToggleButton'><Border Background='#354048' BorderBrush='#435059' BorderThickness='1' CornerRadius='1'/></ControlTemplate></ToggleButton.Template></ToggleButton><Grid IsHitTestVisible='False' Margin='7,3,7,3'><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width='12'/></Grid.ColumnDefinitions><ContentPresenter Content='{TemplateBinding SelectionBoxItem}' VerticalAlignment='Center'/><Path Grid.Column='1' Data='M0,0 L8,0 4,5 Z' Fill='#c0cbd1' VerticalAlignment='Center'/></Grid><Popup x:Name='PART_Popup' Placement='Bottom' IsOpen='{TemplateBinding IsDropDownOpen}' AllowsTransparency='True' Focusable='False'><Border Background='#303b43' BorderBrush='#435059' BorderThickness='1' MinWidth='{TemplateBinding ActualWidth}'><ScrollViewer MaxHeight='300'><ItemsPresenter/></ScrollViewer></Border></Popup></Grid></ControlTemplate></Setter.Value></Setter></Style>";
  Resources[typeof(ComboBox)]=(Style)XamlReader.Parse(combo);
  var button=new Style(typeof(Button));button.Setters.Add(new Setter(Button.TemplateProperty,(ControlTemplate)XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='Button'><Border Background='{TemplateBinding Background}' CornerRadius='2' Padding='{TemplateBinding Padding}'><ContentPresenter HorizontalAlignment='{TemplateBinding HorizontalContentAlignment}' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter Property='Opacity' Value='.82'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.35'/></Trigger></ControlTemplate.Triggers></ControlTemplate>")));Resources[typeof(Button)]=button;
 }
 DrawingImage ToolPicture(string kind){var group=new DrawingGroup();var light=B("#c6ced3");var pen=new Pen(light,2);using(var d=group.Open()){
  d.DrawRectangle(Brushes.Transparent,null,new Rect(0,0,24,24));
  if(kind=="Undo"||kind=="Redo"){var g=Geometry.Parse("M18,20 C23,8 15,4 7,7 M7,7 L7,1 M7,7 L1,7");if(kind=="Redo")d.PushTransform(new ScaleTransform(-1,1,12,12));d.DrawGeometry(null,pen,g);if(kind=="Redo")d.Pop();}
  else if(kind=="Cut"){d.DrawEllipse(null,pen,new Point(6,18),4,4);d.DrawEllipse(null,pen,new Point(18,18),4,4);d.DrawLine(pen,new Point(8,15),new Point(20,2));d.DrawLine(pen,new Point(16,15),new Point(4,2));}
  else if(kind=="Copy"){d.DrawRoundedRectangle(null,pen,new Rect(3,2,14,17),1,1);d.DrawRoundedRectangle(light,null,new Rect(7,6,14,17),1,1);d.DrawLine(new Pen(panel,2),new Point(10,11),new Point(18,11));d.DrawLine(new Pen(panel,2),new Point(10,16),new Point(18,16));}
  else if(kind=="Paste"){d.DrawRoundedRectangle(null,pen,new Rect(5,5,14,17),1,1);d.DrawRoundedRectangle(light,null,new Rect(8,2,8,5),1,1);d.DrawLine(pen,new Point(8,11),new Point(16,11));d.DrawLine(pen,new Point(8,16),new Point(16,16));}
  else if(kind=="Split"){d.DrawRectangle(null,pen,new Rect(2,5,7,15));d.DrawRectangle(null,pen,new Rect(15,5,7,15));d.DrawLine(pen,new Point(12,2),new Point(12,23));}
  else if(kind=="Frame"){d.DrawRoundedRectangle(light,null,new Rect(2,6,20,15),2,2);d.DrawRectangle(light,null,new Rect(7,3,8,5));d.DrawEllipse(panel,null,new Point(12,13),5,5);}
  else if(kind=="Zoom"){d.DrawEllipse(null,pen,new Point(10,10),6,6);d.DrawLine(new Pen(light,3),new Point(14,14),new Point(22,22));}
  else if(kind=="Eye"){d.DrawEllipse(light,null,new Point(12,12),11,6);d.DrawEllipse(panel,null,new Point(12,12),4,4);}
  else if(kind=="Lock"){d.DrawRoundedRectangle(light,null,new Rect(6,10,12,12),1,1);d.DrawRoundedRectangle(null,pen,new Rect(8,2,8,13),4,4);d.DrawEllipse(panel,null,new Point(12,16),2,2);}
  else if(kind=="Snap"){d.DrawGeometry(null,new Pen(light,4),Geometry.Parse("M5,4 L5,15 C5,23 19,23 19,15 L19,4"));d.DrawLine(new Pen(panel,2),new Point(2,9),new Point(8,9));d.DrawLine(new Pen(panel,2),new Point(16,9),new Point(22,9));}
  else if(kind=="Select"){d.DrawGeometry(light,null,Geometry.Parse("M4,2 L4,20 9,15 13,23 17,21 13,13 21,13 Z"));}
  else if(kind=="Crop"){d.DrawGeometry(null,pen,Geometry.Parse("M6,1 L6,18 L23,18 M1,6 L18,6 L18,23 M10,10 L14,10 L14,14"));}
  else if(kind=="Pan"){d.DrawGeometry(null,pen,Geometry.Parse("M5,12 L5,18 C5,25 19,25 19,18 L19,9 M5,15 L2,11 M8,15 L8,3 M12,15 L12,1 M16,15 L16,4"));}
  else if(kind=="Home"){d.DrawGeometry(light,null,Geometry.Parse("M12,2 L23,12 L20,12 L20,22 L14.5,22 L14.5,15 L9.5,15 L9.5,22 L4,22 L4,12 L1,12 Z"));}
  else if(kind=="RecordDot"){d.DrawEllipse(Brushes.White,null,new Point(12,12),10,10);d.DrawEllipse(B("#e53935"),null,new Point(12,12),7.5,7.5);}
  else if(kind=="Share"){d.DrawGeometry(null,new Pen(Brushes.White,2),Geometry.Parse("M8,9 L4,9 L4,22 L20,22 L20,9 L16,9 M12,15 L12,2 M7,7 L12,2 L17,7"));}
  else if(kind=="Gear"){var g=new StreamGeometry();using(var c=g.Open()){for(int i=0;i<8;i++){double a=i*Math.PI/4,w=.28;c.BeginFigure(new Point(12+11*Math.Cos(a-w),12+11*Math.Sin(a-w)),true,true);c.LineTo(new Point(12+11*Math.Cos(a+w),12+11*Math.Sin(a+w)),false,false);c.LineTo(new Point(12+7*Math.Cos(a+w+.2),12+7*Math.Sin(a+w+.2)),false,false);c.LineTo(new Point(12+7*Math.Cos(a-w-.2),12+7*Math.Sin(a-w-.2)),false,false);}}d.DrawGeometry(Brushes.White,null,g);d.DrawEllipse(null,new Pen(Brushes.White,3.4),new Point(12,12),6.3,6.3);}
  else if(kind=="Play"){d.DrawGeometry(Brushes.White,null,Geometry.Parse("M7,3 L21,12 L7,21 Z"));}
  else if(kind=="Pause"){d.DrawRectangle(Brushes.White,null,new Rect(6,4,4,16));d.DrawRectangle(Brushes.White,null,new Rect(14,4,4,16));}
  else if(kind=="PrevFrame"){d.DrawRectangle(light,null,new Rect(16,5,3,14));d.DrawGeometry(light,null,Geometry.Parse("M14,5 L4,12 L14,19 Z"));}
  else if(kind=="NextFrame"){d.DrawRectangle(light,null,new Rect(5,5,3,14));d.DrawGeometry(light,null,Geometry.Parse("M10,5 L20,12 L10,19 Z"));}
  else if(kind=="PrevMedia"||kind=="NextMedia"||kind=="Chevron"){var round=new Pen(light,2.6){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round,LineJoin=PenLineJoin.Round};d.DrawGeometry(null,round,Geometry.Parse(kind=="PrevMedia"?"M15,5 L8,12 L15,19":"M9,5 L16,12 L9,19"));}
  else if(kind=="Plus"||kind=="Minus"){var p=new Pen(light,2.4);d.DrawLine(p,new Point(5,12),new Point(19,12));if(kind=="Plus")d.DrawLine(p,new Point(12,5),new Point(12,19));}
  else if(kind=="MarkerTrayOpen"||kind=="MarkerTrayClosed"){var round=new Pen(light,2.4){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round,LineJoin=PenLineJoin.Round};d.DrawGeometry(null,round,Geometry.Parse(kind=="MarkerTrayOpen"?"M6,15 L12,9 L18,15":"M6,9 L12,15 L18,9"));}
  else if(kind=="Favorites"){var g=new StreamGeometry();using(var s=g.Open()){for(int i=0;i<10;i++){double r=i%2==0?11:4.6,a=i*Math.PI/5-Math.PI/2;var p=new Point(12+r*Math.Cos(a),12.5+r*Math.Sin(a));if(i==0)s.BeginFigure(p,true,true);else s.LineTo(p,false,false);}}d.DrawGeometry(light,null,g);}
  else if(kind=="Behaviors"){d.DrawRectangle(light,null,new Rect(2,9,5,5));d.DrawRectangle(light,null,new Rect(9,13,5,5));d.DrawRectangle(light,null,new Rect(16,18,5,5));d.DrawLine(new Pen(light,1.5),new Point(11.5,2),new Point(11.5,10));d.DrawLine(new Pen(light,1.5),new Point(18.5,6),new Point(18.5,15));}
  else if(kind=="Meter"){for(int i=0;i<2;i++)d.DrawRoundedRectangle(light,null,new Rect(2,6+i*7,20,4),2,2);}
  else if(kind=="Media"){d.DrawRectangle(null,pen,new Rect(2,4,20,16));for(int i=0;i<5;i++){d.DrawRectangle(light,null,new Rect(3.5+i*4,5.5,2,2));d.DrawRectangle(light,null,new Rect(3.5+i*4,16.5,2,2));}d.DrawLine(new Pen(light,1),new Point(2,9),new Point(22,9));d.DrawLine(new Pen(light,1),new Point(2,15),new Point(22,15));}
  else if(kind=="Library"){d.DrawRectangle(light,null,new Rect(3,4,4,17));d.DrawRectangle(light,null,new Rect(9,6,4,15));d.PushTransform(new RotateTransform(-18,17,21));d.DrawRectangle(light,null,new Rect(15,5,4,16));d.Pop();}
  else if(kind=="Annotations"){d.DrawGeometry(light,null,Geometry.Parse("M2,3 L22,3 L22,17 L10,17 L5,22 L5,17 L2,17 Z"));var text=new FormattedText("a",System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface(new FontFamily("Segoe UI"),FontStyles.Normal,FontWeights.Bold,FontStretches.Normal),12,panel,1.0);d.DrawText(text,new Point(12-text.Width/2,2.5));}
  else if(kind=="VisualEffects"){d.DrawLine(new Pen(light,3){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round},new Point(4,21),new Point(15,10));foreach(var s in new[]{new Point(18,4),new Point(21,10),new Point(11,4)})d.DrawGeometry(light,null,Sparkle(s));}
  else if(kind=="Transitions"){d.DrawRectangle(null,pen,new Rect(2,5,20,14));d.DrawGeometry(light,null,Geometry.Parse("M22,5 L22,19 L2,19 Z"));}
  else if(kind=="Animations"){d.DrawLine(new Pen(light,2),new Point(2,12),new Point(16,12));d.DrawGeometry(light,null,Geometry.Parse("M11,7 L17,12 L11,17 Z"));d.DrawEllipse(light,null,new Point(20,12),2.6,2.6);}
  else if(kind=="AudioEffects"){foreach(var bar in new[]{new Rect(2,9,3,6),new Rect(7,5,3,14),new Rect(12,2,3,20),new Rect(17,7,3,10)})d.DrawRoundedRectangle(light,null,bar,1.5,1.5);}
  else if(kind=="Captions"){d.DrawRoundedRectangle(null,pen,new Rect(2,4,20,16),3,3);var text=new FormattedText("CC",System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface(new FontFamily("Segoe UI"),FontStyles.Normal,FontWeights.Bold,FontStretches.Normal),9.5,light,1.0);d.DrawText(text,new Point(12-text.Width/2,12-text.Height/2));}
 }var image=new DrawingImage(group);image.Freeze();return image;}
 static Geometry Sparkle(Point c){var g=new StreamGeometry();using(var s=g.Open()){for(int i=0;i<8;i++){double r=i%2==0?3:1,a=i*Math.PI/4-Math.PI/2;var p=new Point(c.X+r*Math.Cos(a),c.Y+r*Math.Sin(a));if(i==0)s.BeginFigure(p,true,true);else s.LineTo(p,false,false);}}g.Freeze();return g;}
 Image Glyph(string kind,double size){return new Image{Source=ToolPicture(kind),Width=size,Height=size,VerticalAlignment=VerticalAlignment.Center};}
 Button CircleButton(string label,string kind,Action action,double size,double iconSize){var b=IconButton(label,kind,action);b.Content=Glyph(kind,iconSize);b.Width=b.Height=size;b.Padding=new Thickness(0);b.Margin=new Thickness(4,0,4,0);b.Background=B("#353e45");string radius=(size/2).ToString(System.Globalization.CultureInfo.InvariantCulture);b.Template=(ControlTemplate)XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='Button'><Border Background='{TemplateBinding Background}' CornerRadius='"+radius+"'><ContentPresenter HorizontalAlignment='Center' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter Property='Opacity' Value='.82'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.35'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");return b;}
 Button LabeledButton(string text,string kind,string tooltip,Action action,bool green){var b=Btn(text,action,green);var content=new StackPanel{Orientation=Orientation.Horizontal};content.Children.Add(Glyph(kind,18));content.Children.Add(new TextBlock{Text=text,Margin=new Thickness(8,0,0,0),VerticalAlignment=VerticalAlignment.Center,FontWeight=FontWeights.SemiBold});b.Content=content;b.ToolTip=tooltip;AutomationProperties.SetName(b,text);return b;}
 Button IconButton(string label,string kind,Action action){var b=Btn(label,action);b.Content=new Image{Source=ToolPicture(kind),Width=18,Height=18};b.Width=30;b.Height=26;b.Padding=new Thickness(5);b.Margin=new Thickness(1);b.Background=B("#252d33");b.ToolTip=label;AutomationProperties.SetName(b,label);AutomationProperties.SetAutomationId(b,"Tool."+kind);return b;}
 void UpdatePlayUi(){if(play==null)return;play.Content=Glyph(playing?"Pause":"Play",24);string label=playing?"Pause (Spacebar)":"Play (Spacebar)";play.ToolTip=label;AutomationProperties.SetName(play,label);}
 void ExportFrame(){if(live==null)return;Pause();var d=new SaveFileDialog{Filter="PNG image|*.png",FileName="TasiaCraft-frame.png"};if(d.ShowDialog()!=true)return;try{if(project.Media.Exists(m=>string.Equals(Path.GetFullPath(m.Path),Path.GetFullPath(d.FileName),StringComparison.OrdinalIgnoreCase)))throw new Exception("Cannot overwrite source media.");live.SetSelection(null);live.Stage.UpdateLayout();var bitmap=new RenderTargetBitmap(project.Width,project.Height,96,96,PixelFormats.Pbgra32);bitmap.Render(live.Stage);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(d.FileName))encoder.Save(f);Info("Frame saved: "+d.FileName);}catch(Exception e){MessageBox.Show(e.Message,"Frame export");}finally{SyncSelection();}}
}
